C373_R = [('z.sense * 0.91', 'z.sense * 0.91 * chHydK()', 4), ("    for (const z of zombies) if (z.mut && !(TEST_ARMOR && z.mut === 'armor') && (z.mutT -= dt) <= 0) unmutate(z);   // 변이 끝", "    if (CHAPTER) for (const z of zombies) if (z.mut === 'armor') z.force = 11 * chArmK();   // c373: 덩치 미는 힘 = 원래(11)의 2/3 · 촉매제로 1.2배까지\n    for (const z of zombies) if (z.mut && !(TEST_ARMOR && z.mut === 'armor') && (z.mutT -= dt) <= 0) unmutate(z);   // 변이 끝"), ("(CHAPTER && z.mut && owned.catalyst ? 1 + 0.1 * (1 + lv('catalyst')) : 1", "(false ? 1 + 0.1 * (1 + lv('catalyst')) : 1   /* c373: 촉매제 공격력 효과 없앰 */"), ("    if (CHAPTER && owned.catalyst) { z.catK = 1 + 0.05 * (1 + lv('catalyst')); z.maxHp *= z.catK; }   // c282: 촉매제 — 변이하는 동안 최대 체력 +5%씩", '    // c373: 촉매제 최대 체력 효과 없앰 (c282)'), ("    if (CHAPTER && owned.catalyst) { me.catK = 1 + 0.05 * (1 + lv('catalyst')); me.maxHp *= me.catK; me.hp *= me.catK; }   // c282: 각성한 나도 (체력 비율은 그대로)", '    // c373: 촉매제 최대 체력 효과 없앰 (c282)'), ('  function mutate(z, force) {', "  function chCatT() { return CHAPTER && owned.catalyst ? (1 + lv('catalyst')) / 6 : 0; }   // c373: 촉매제 진행 (획득 1/6 … 다 강화 6/6)\n  function chHydK() { return CHAPTER ? 2 / 3 + (1.3 - 2 / 3) * chCatT() : 1; }   // c373: 히드라 사거리 — 원래의 2/3, 촉매제 다 올리면 1.3배\n  function chArmK() { return 2 / 3 + (1.2 - 2 / 3) * chCatT(); }   // c373: 덩치 미는 힘 — 원래의 2/3, 촉매제 다 올리면 1.2배\n  function mutate(z, force) {"), ("const bookCut = () => owned.book ? 0.07 * (1 + lv('book')) : 0;", "const bookCut = () => owned.book ? (CHAPTER ? 0.05 + 0.09 * lv('book') : 0.07 * (1 + lv('book'))) : 0;   /* c373: 5% · 14 · 23 · 32 · 41 · 50% */"), ('book: (n) => `무기 쿨타임 -${7 * (1 + n)}%`', 'book: (n) => `무기 쿨타임 -${5 + 9 * n}%`'), ("book: ['쿨타임', (n) => `-${7 * (1 + n)}%`]", "book: ['쿨타임', (n) => `-${5 + 9 * n}%`]"), ("catalyst: ['공격', (n) => `+${10 * (1 + n)}%`]", "catalyst: ['변이', (n) => `+${Math.round((1 + n) / 6 * 100)}%`]"), ("catalyst: '변이한 좀비의 공격력과 최대 체력이 함께 오릅니다. 강화하면 더 오릅니다.'", "catalyst: '히드라 좀비의 사거리와 덩치 좀비의 미는 힘이 늘어납니다. 얻은 변이 좀비, 만들어 낸 변이 좀비 모두에게 적용됩니다. 다 강화하면 히드라 사거리 1.3배, 덩치 미는 힘 1.2배가 됩니다.'"), ("catalyst: '변이 좀비 공격력·체력 증가'", "catalyst: '히드라 사거리·덩치 미는 힘 증가'"), ("    catalyst: ['변이한 좀비의 공격력과 최대 체력이 오릅니다.', '강화 시 더 오릅니다.'],", "    catalyst: ['히드라 좀비의 사거리와 덩치 좀비의 미는 힘이 늘어납니다.', '강화 시 더 늘어납니다.'],"), ('    catalyst: (n) => `변이 좀비 공격력 +${10 * (1 + n)}% · 최대 체력 +${5 * (1 + n)}%`,', '    catalyst: (n) => `히드라 사거리 x${(2 / 3 + (1.3 - 2 / 3) * (1 + n) / 6).toFixed(2)} · 덩치 미는 힘 x${(2 / 3 + (1.2 - 2 / 3) * (1 + n) / 6).toFixed(2)} (지금 값 1 기준, 없으면 x0.67)`,')]
